code='''def transform(grid):
    g=[row[:] for row in grid]
    w=max(map(len,g))
    for row in g: row.extend([8]*(w-len(row)))
    h=len(g); bg=max(set(v for row in g for v in row), key=lambda v: sum(row.count(v) for row in g))
    seen=set()
    for r in range(h):
      for x in range(w):
        c=g[r][x]
        if c==bg or (r,x) in seen: continue
        stack=[(r,x)]; seen.add((r,x)); pts=[]
        while stack:
          a,b=stack.pop(); pts.append((a,b))
          for q in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
            if 0<=q[0]<h and 0<=q[1]<w and q not in seen and g[q[0]][q[1]]==c: seen.add(q); stack.append(q)
        r0=min(a for a,b in pts); r1=max(a for a,b in pts); x0=min(b for a,b in pts); x1=max(b for a,b in pts)
        if r1-r0<2 or x1-x0<2: continue
        if all(g[r0][b]==c and g[r1][b]==c for b in range(x0,x1+1)) and all(g[a][x0]==c and g[a][x1]==c for a in range(r0,r1+1)):
          fill=7 if (r1-r0+1)%2 else 2
          for a in range(r0+1,r1):
            for b in range(x0+1,x1):
              if g[a][b]==bg: g[a][b]=fill
    return g
'''
